// TH18 v1.00a Extra, stage 7 wave: st07.ecl.txt::MainSub07:1363-1380
// Dependencies: GirlD02:793-819, GirlD02_at:821-845, GirlD02_at2:847-872.
//
// Source/card timing: MainSub07 creates the five GirlD02 at source t=0/200/400/540/640.
// This card starts the pattern after OPENING_BUFFER=120; each enemy task and its two
// shoot tasks first run on the next frame, matching the source async first-run delay.
//
// Source etSprite type20/color2 -> TH18 type20 is TH18_OVAL (logical row base 672), color 2.
const TH18_OVAL: int = 672;

const TIME_LIMIT: int = 2780;
const OPENING_BUFFER: int = 120;

// Source ex records on every shot (GirlD02_at:831-833 / GirlD02_at2:858-860):
//   ANIM(a=1) omitted with the approved birth-animation omission; its -4*velocity
//   birth offset is kept through sh_dist(-2fx) (initial speed 0.5).
//   OFFSCREEN(a=300,b=0) -> offscreen_keep(300).
//   ANGLE_ACCEL(a=200,r=0.03,s=%F0=+/-1deg/frame) -> set_ang_vel(sign) +
//   set_accel(0.03fx), both cleared after 200 updates.
xformdef GIRL_SHOT(sign: angle) {
    offscreen_keep(300);
    set_ang_vel(sign);
    @200 set_accel(0.03fx);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// GirlD02_at / GirlD02_at2: same emitter configuration in two async tasks.
// Source slots 0 and 1 are separate; target shooters are per task, so each task uses 0.
// Source: wait(60) / wait(50); etCount(8,1); etAngle(pi/2,3deg); etSpeed(0.5,1.5);
// mode3 fixed-direction ring; 15 volleys every 20 frames, base angle starting at
// 112.5deg and stepping +222.5deg (2*pi - 137.5deg) each volley.
async sub shot_stream(sign: angle, delay: int) {
    wait(delay);
    sh_reset(0);
    sh_sprite(0, TH18_OVAL, 2);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 8, 1);
    sh_speed(0, 0.5fx, 0fx);
    sh_angle(0, 20480bam, 3deg);
    sh_dist(0, -2fx);
    sh_xform(0, GIRL_SHOT(sign));
    var a: angle = 20480bam; // 112.5deg
    for i in 0..15 {
        sh_angle(0, a, 3deg);
        sh_fire(0);
        a = a + 40506bam; // 222.5deg
        wait(20);
    }
}

// GirlD02:793-819, with the approved enemy shell (real circular bodies, invincible).
// setHurtbox(32,32) -> radius 16; setHitbox(24,24) -> radius 12.
// The 850-frame speed reversal is kept: moveSpeedTime(120,1,-2.3) at t=850.
async sub girl(sign: angle) {
    set_invuln(65535);
    set_hitbox(12fx);
    set_hurtbox(16fx);
    spawn shot_stream(sign, 60);
    spawn shot_stream(sign, 50);
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN); // mode1: 3 -> 0 over 60
    wait(250);
    move_speed(120, 0.15fx, EASE_QUAD_IN); // mode1: 0 -> 0.15 over 120
    wait(600);
    move_speed(120, -2.3fx, EASE_QUAD_IN); // t=850 return: 0.15 -> -2.3
    wait(60);
    loop { wait(1000); } // source GirlD02_524 wait(1000) loop
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // enmCreate positions are relative to the stage-parent FINAL (0,0) here.
    // %F0 alternates +, -, +, -, + across the five creations.
    _ = spawn_enemy(0fx, -32fx, 4000, 0, 0, 0, girl(1deg));
    wait(200);
    _ = spawn_enemy(32fx, -32fx, 4000, 0, 0, 0, girl(-1deg));
    wait(200);
    _ = spawn_enemy(-32fx, -32fx, 4000, 0, 0, 0, girl(1deg));
    wait(140);
    _ = spawn_enemy(48fx, -32fx, 3500, 0, 0, 0, girl(-1deg));
    wait(100);
    _ = spawn_enemy(-48fx, -32fx, 3500, 0, 0, 0, girl(1deg));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    var rank: int = global(GVAR_RANK);
    if rank == RANK_EXTRA {
        _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    }
    loop { wait(600); }
}
